Let $A$, $B$, $C$ be $m\times n$ matrices and $k$, $\ell$ be scalars.
Then:
\begin{enumerate}[leftmargin=2em, itemsep=4pt]
  \item $A + B = B + A$ \hfill\textit{(Commutativity of Addition)}
  \item $(A+B)+C = A+(B+C)$
        \hfill\textit{(Associativity of Addition)}
  \item $A + \mathbf{0} = A$ \hfill\textit{(Additive Identity)}
  \item $A + (-A) = \mathbf{0}$ \hfill\textit{(Additive Inverse)}
  \item $k(A+B) = kA + kB$ \hfill\textit{(Distributivity I)}
  \item $(k+\ell)A = kA + \ell A$ \hfill\textit{(Distributivity II)}
  \item $k(\ell A) = (k\ell)A$
        \hfill\textit{(Associativity of Scalar Mult.)}
  \item $1 \cdot A = A$ \hfill\textit{(Scalar Identity)}
\end{enumerate}

Let $A$, $B$, $C$ be matrices of sizes for which the operations
are defined and $k$ be a scalar. Then:
\begin{enumerate}[leftmargin=2em, itemsep=4pt]
  \item $(AB)C = A(BC)$ \hfill\textit{(Associativity)}
  \item $A(B+C) = AB + AC$ \hfill\textit{(Left Distributivity)}
  \item $(A+B)C = AC + BC$ \hfill\textit{(Right Distributivity)}
  \item $k(AB) = (kA)B = A(kB)$
        \hfill\textit{(Scalar Associativity)}
  \item $AI = IA = A$ \hfill\textit{(Identity)}
\end{enumerate}
\textbf{The following properties do NOT hold in general:}
\begin{itemize}[leftmargin=1.5em, itemsep=3pt]
  \item $AB \neq BA$ \hfill\textit{(commutative law fails)}
  \item $AB = \mathbf{0} \not\Rightarrow A=\mathbf{0}$
        or $B=\mathbf{0}$ \hfill\textit{(zero-product law fails)}
  \item $AB = AC \not\Rightarrow B = C$
        \hfill\textit{(cancellation law fails)}
\end{itemize}

\textbf{Summary --- Three Laws That Fail for Matrices:}
\begin{enumerate}[leftmargin=2em, itemsep=5pt]
  \item $AB \neq BA$ in general \hfill
        \textit{(commutative law fails)}
  \item $AB = \mathbf{0}$ does \textbf{not} imply
        $A = \mathbf{0}$ or $B = \mathbf{0}$
        \hfill\textit{(zero-product law fails)}
  \item $AB = AC$ does \textbf{not} imply $B = C$
        \hfill\textit{(cancellation law fails)}
\end{enumerate}

Let $A = \begin{bmatrix} 1 & 1 \\ 0 & 1 \end{bmatrix}$.
Compute $A^2$ and $A^3$.

\textbf{Solution:}
\[
A^2 = AA =
\begin{bmatrix}1&1\\0&1\end{bmatrix}
\begin{bmatrix}1&1\\0&1\end{bmatrix}
=
\begin{bmatrix}1+0 & 1+1\\0 & 0+1\end{bmatrix}
=
\begin{bmatrix}1&2\\0&1\end{bmatrix}.
\]
\[
A^3 = A^2 \cdot A =
\begin{bmatrix}1&2\\0&1\end{bmatrix}
\begin{bmatrix}1&1\\0&1\end{bmatrix}
=
\begin{bmatrix}1&3\\0&1\end{bmatrix}.
\]

\bigskip

Find the inverse of
$A = \begin{bmatrix}3 & 1\\5 & 2\end{bmatrix}$.

\textbf{Solution:}
$\det(A) = (3)(2)-(1)(5) = 6-5 = 1 \neq 0$, so $A$ is invertible.
\[
A^{-1} = \frac{1}{1}\begin{bmatrix}2&-1\\-5&3\end{bmatrix}
=
\begin{bmatrix}2&-1\\-5&3\end{bmatrix}.
\]
\textbf{Verification:} $AA^{-1} =
\begin{bmatrix}3&1\\5&2\end{bmatrix}
\begin{bmatrix}2&-1\\-5&3\end{bmatrix}
= \begin{bmatrix}6-5&-3+3\\10-10&-5+6\end{bmatrix}
= \begin{bmatrix}1&0\\0&1\end{bmatrix} = I$. \checkmark

\bigskip

Define a unitary matrix. Is
$U = \dfrac{1}{\sqrt{2}}\begin{bmatrix}1 & i \\ i & 1\end{bmatrix}$
unitary?

\textbf{Solution:}
A square matrix $U$ is \textbf{unitary} if $U^* U = I$.

Compute $U^*$:
\[
U^* = \frac{1}{\sqrt{2}}\begin{bmatrix}1 & -i \\ -i & 1\end{bmatrix}.
\]
Now compute $U^* U$:
\[
U^* U =
\frac{1}{2}
\begin{bmatrix}1&-i\\-i&1\end{bmatrix}
\begin{bmatrix}1&i\\i&1\end{bmatrix}
=
\frac{1}{2}
\begin{bmatrix}1+1 & i-i \\ -i+i & 1+1\end{bmatrix}
=
\frac{1}{2}
\begin{bmatrix}2&0\\0&2\end{bmatrix}
=
\begin{bmatrix}1&0\\0&1\end{bmatrix} = I.
\]
Since $U^* U = I$, the matrix $U$ is \textbf{unitary}. \hfill$\square$

If $A$ is an orthogonal matrix, show that $\det(A)=\pm1$.

\textbf{Solution:}
Since $A$ is orthogonal, $A^TA=I$. Taking determinants:
\[
\det(A^TA)=\det(I)=1
\;\Rightarrow\;
\det(A^T)\cdot\det(A)=1
\;\Rightarrow\;
[\det(A)]^2=1
\;\Rightarrow\;
\det(A)=\pm1.\quad\square
\]

\bigskip

Show that if $A$ is an $n\times n$ skew-symmetric matrix
        and $n$ is odd, then $\det(A)=0$.
        \textit{Hint: Use $\det(A^T)=\det(A)$ and $A^T=-A$.}
